package io.github.alien2003.teamsbridge.proto

import org.json.JSONArray
import org.json.JSONObject
import java.io.File

/**
 * proto/vectors.json, generated by the Go side. The Gradle test task passes its absolute path as the
 * system property `tbd.vectors` (android/app/build.gradle.kts).
 */
object TestVectors {
    val root: JSONObject by lazy {
        val path = System.getProperty("tbd.vectors") ?: error("system property tbd.vectors is not set (run through Gradle)")
        JSONObject(File(path).readText(Charsets.UTF_8))
    }

    val secret: ByteArray get() = hex(root.getString("secret_hex"))
    val key: ByteArray get() = hex(root.getString("key_hex"))
    val messages: List<JSONObject> get() = objects(root.getJSONArray("messages"))
    val codeInputs: List<JSONObject> get() = objects(root.getJSONArray("code_inputs"))
    val invalidSealed: List<JSONObject> get() = objects(root.getJSONArray("invalid_sealed"))

    private fun objects(a: JSONArray): List<JSONObject> = List(a.length()) { a.getJSONObject(it) }
}

fun hex(s: String): ByteArray {
    require(s.length % 2 == 0) { "odd hex length" }
    return ByteArray(s.length / 2) { i -> s.substring(2 * i, 2 * i + 2).toInt(16).toByte() }
}

fun ByteArray.toHex(): String = joinToString("") { "%02x".format(it.toInt() and 0xFF) }
